// Разбор команды: `clip <imageUrl> | <prompt> | <caption>`
const msg = $json.message ?? {};
const text = (msg.text ?? '').trim();
const chatId = msg.chat?.id;
const m = text.match(/^clip\s+(\S+)\s*\|\s*([^|]+?)\s*(?:\|\s*(.+))?$/is);
if (m) {
  return [{ json: { mode: 'clip', chatId, imageUrl: m[1], prompt: m[2].trim(), caption: (m[3] ?? '').trim() } }];
}
return [{ json: { mode: 'help', chatId } }];
